local_checks.script:
import {isMoneyString,assertMoneyString} from './packages/domain/src/envelope.mjs';
const invalid=[1n,1,1.5,'-1','1.0','00',((1n<<128n)).toString()];
for(const v of invalid){if(isMoneyString(v))throw Error('invalid accepted'); let denied=false; try{assertMoneyString(v)}catch{denied=true}if(!denied)throw Error('assert accepted invalid');}
for(const v of ['0','5000000',((1n<<128n)-1n).toString()]){if(!isMoneyString(v)||assertMoneyString(v).toString()!==v)throw Error('valid rejected');}
console.log('PASS_LOCAL: JSON money strings reject bigint/numbers/invalid values; valid canonical u128 strings retained');
